struct Notifier; impl Notifier { fn send_sms(&self,id:u32,text:&str)->Result<(),()> { let p=self.get_phone(id)?; self.send(&p,text); if !self.validate_phone(&p){return Ok(());} Ok(()) } fn get_phone(&self,_:u32)->Result<String,()>{Ok("1".into())} fn validate_phone(&self,_:&str)->bool{true} fn send(&self,_:&str,_:&str){} }
